import 'package:freezed_annotation/freezed_annotation.dart';

part 'page_font_manifest_models.freezed.dart';

/// One page's verified font, generated by
/// `tool/quran_data/src/qpc_font_package.dart` from the real QCF V2 font
/// package — never hand-written. [fontFamily] is read from the font file's
/// own `name` table (nameID 1), not derived from [sourceFile]'s filename,
/// so a mismatch between the package's own filenames and its embedded
/// family names is caught at generation time rather than trusted blindly.
@freezed
abstract class PageFontManifestEntry with _$PageFontManifestEntry {
  const factory PageFontManifestEntry({
    required int mushafId,
    required int pageNumber,

    /// Path Flutter's `rootBundle` resolves this file at (relative to the
    /// app root, e.g. `assets/quran/fonts/qpc_v2/QCF2001.ttf`).
    required String assetPath,

    /// The exact family name to pass as `TextStyle.fontFamily` after
    /// registering this file via `dart:ui`'s `FontLoader` — read from the
    /// font's own embedded `name` table, not assumed from a filename
    /// pattern.
    required String fontFamily,

    /// The original filename inside the vendored QPC V2 font package (e.g.
    /// `p1.ttf`) — kept for traceability back to the source package.
    required String sourceFile,
    required String fileHash,
    required int fileSize,
  }) = _PageFontManifestEntry;
}

/// The full page->font mapping for one Mushaf edition, plus enough
/// provenance to know exactly which upstream font package it was generated
/// from.
@freezed
abstract class PageFontManifest with _$PageFontManifest {
  const factory PageFontManifest({
    required int schemaVersion,
    required int mushafId,
    required String fontPackageSource,
    required String fontPackageHash,
    required DateTime generatedAt,
    required List<PageFontManifestEntry> entries,
  }) = _PageFontManifest;
}
